for f, blocs in REMPLACEMENTS.items():
    chemin = os.path.join(racine, "monde", "pays", f + ".py")
    s = open(chemin).read()
    faits = deja = 0
    for variantes in blocs:                      # la forme du tronc, puis celle de la reference d origine
        if any(neuf in s for _, neuf in variantes): deja += 1; continue
        v = next(((vieux, neuf) for vieux, neuf in variantes if s.count(vieux) == 1), None)
        if v is None:
            if any(m in variantes[0][0] or m in variantes[0][1] for m in FACULTATIFS): continue
            raise AssertionError((chemin, variantes[0][0][:160]))
        s = s.replace(v[0], v[1]); faits += 1
    open(chemin, "w").write(s); print("corrige :" if faits else "deja corrige :", chemin, faits, "remplacements", deja, "deja faits")
